--- /dev/null
+++ b/services/orders-api/summary_cache.go
@@ -0,0 +1,14 @@
+func (r *Repo) GetOrderSummary(ctx context.Context, orderID string) (*Summary, error) {
+	if !r.flags.Enabled("orders_summary_cache") {
+		return r.loadSummaryFromDB(ctx, orderID)
+	}
+	if s, ok := r.summaryCache.Get(orderID); ok {
+		return s, nil
+	}
+	s, err := r.loadSummaryFromDB(ctx, orderID)
+	if err != nil {
+		return nil, err
+	}
+	r.summaryCache.Set(orderID, s)
+	return s, nil
+}

